SourceCode.Declaration:
/// <summary>
/// One worker session for HSMobileOpsSignInLogService::logSession. Times are milliseconds since
/// 1 Jan 1970 UTC, as the handheld keeps them; SignOutMillis is 0 while the session is open.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSignInLogRequest
{
    str sessionId;
    str dataAreaId;
    str userName;
    str deviceId;
    str deviceName;
    str warehouseId;
    str appVersionName;
    boolean signedInOffline;
    int64 signInMillis;
    int64 signOutMillis;
    str endReason;
}

Method.Source:
